#
# The MESSI output contract for Python methods. Everything messi_run.py writes goes
# through these validators, and so does `add_method.py check`.
# Needs numpy and pandas only: no MuData, so the self-check runs anywhere.

import hashlib
import importlib
import json

import numpy as np
import pandas as pd

RESULT_COLUMNS = ["sample_name", "y", "phat", "method_name", "dataset", "fold"]
FEATURE_COLUMNS = ["feature", "view", "coef", "method", "dataset_name"]
FEATURE_INPUT_COLUMNS = ["feature", "view", "coef"]
HYPERPARAMETER_FIELDS = ["dataset", "method", "analysis_stage", "parameters"]
TREATMENTS = ["tuned", "fixed", "default", "data-derived"]
PHAT_DECIMALS = 3


class ContractError(Exception):
    pass


def contract_fail(where, got, expected):
    raise ContractError(
        "CONTRACT ERROR in {}\n  got:      {}\n  expected: {}".format(where, got, expected)
    )


def describe(x):
    if x is None:
        return "None"
    if isinstance(x, pd.DataFrame):
        return "a DataFrame with {} rows and columns: {}".format(
            len(x), ", ".join(str(c) for c in x.columns)
        )
    if isinstance(x, pd.Series):
        return "a Series of length {} and dtype {}".format(len(x), x.dtype)
    if isinstance(x, np.ndarray):
        return "an array of shape {} and dtype {}".format(x.shape, x.dtype)
    if isinstance(x, (list, tuple, dict)):
        return "a {} of length {}".format(type(x).__name__, len(x))
    return "an object of type {}".format(type(x).__name__)


def load_core(method):
    """Import <method>_core from the folder of messi_run.py and check the three functions."""
    core_file = method + "_core.py"
    core = importlib.import_module(method + "_core")
    for name in ("fit", "predict_proba", "feature_weights"):
        if not callable(getattr(core, name, None)):
            contract_fail(
                core_file,
                "no function called {}()".format(name),
                "the file defines fit(), predict_proba() and feature_weights()",
            )
    return core


def validate_plain_data(data, where):
    """X is a dict of samples x features DataFrames with identical index, y a 0/1 array."""
    X, y = data["X"], data["y"]
    if not isinstance(X, dict) or not X:
        contract_fail(where, describe(X), "a non-empty dict of views")
    first = next(iter(X.values()))
    samples = list(first.index)
    if len(set(samples)) != len(samples):
        contract_fail(where, "duplicated sample names", "unique sample names")
    for view, frame in X.items():
        if not isinstance(frame, pd.DataFrame):
            contract_fail(where, "view '{}' is {}".format(view, describe(frame)), "a DataFrame")
        if list(frame.index) != samples:
            contract_fail(
                where,
                "view '{}' has different samples or sample order".format(view),
                "the same index, in the same order, in every view",
            )
        if not frame.columns.is_unique:
            contract_fail(where, "view '{}' has duplicated feature names".format(view), "unique columns")
    y = np.asarray(y)
    if y.shape != (len(samples),) or not np.isin(y, [0, 1]).all():
        contract_fail(where, "y is {}".format(describe(y)), "{} labels, each 0 or 1".format(len(samples)))
    return data


def validate_model(model):
    if model is None:
        contract_fail("fit()", "None", "any object holding the fitted model")
    return model


def validate_predictions(phat, samples):
    """Return the scores as a 1-D float array."""
    where = "predict_proba()"
    samples = [str(s) for s in samples]
    expected = (
        "a numeric 1-D array of {} positive-class scores in [0, 1], one per row of X_test, "
        "in the same order".format(len(samples))
    )
    if phat is None or isinstance(phat, dict):
        contract_fail(where, describe(phat), expected)
    labels = None
    if isinstance(phat, (pd.Series, pd.DataFrame)):
        labels = phat.index
    values = phat.values if isinstance(phat, (pd.Series, pd.DataFrame)) else np.asarray(phat)
    if values.ndim == 2 and values.shape[1] == 1:
        values = values[:, 0]
    if values.ndim != 1:
        hint = ""
        if values.ndim == 2:
            hint = ". Return only the column with the probability of class 1, such as proba[:, 1]"
        contract_fail(where, describe(values) + hint, expected)
    if values.dtype == bool or not np.issubdtype(values.dtype, np.number):
        contract_fail(where, describe(values), expected)
    if len(values) != len(samples):
        contract_fail(where, describe(values), expected)
    if labels is not None and not isinstance(labels, pd.RangeIndex):
        if [str(s) for s in labels] != samples:
            contract_fail(
                where,
                "a pandas object whose index does not match the test samples in order",
                "the index of X_test, or a plain numpy array",
            )
    values = values.astype(float)
    if np.isnan(values).any():
        contract_fail(where, "{} NaN values out of {}".format(int(np.isnan(values).sum()), len(values)), expected)
    if not np.isfinite(values).all() or values.min() < 0 or values.max() > 1:
        contract_fail(
            where,
            "values from {} to {}".format(values.min(), values.max()),
            expected + ". The metrics threshold phat and compute a log loss, "
            "so raw scores must be turned into probabilities",
        )
    return values


def validate_features(table, X):
    """Return a DataFrame with exactly the columns feature, view, coef."""
    where = "feature_weights()"
    expected = "a DataFrame with columns feature, view, coef and at least one row"
    if isinstance(table, dict):
        try:
            table = pd.DataFrame(table)
        except ValueError:
            contract_fail(where, "a dict that is not a table", expected)
    if not isinstance(table, pd.DataFrame):
        contract_fail(where, describe(table), expected)
    missing = [c for c in FEATURE_INPUT_COLUMNS if c not in table.columns]
    if missing:
        contract_fail(where, "{}. Missing: {}".format(describe(table), ", ".join(missing)), expected)
    if table.empty:
        contract_fail(where, "a table with 0 rows", expected)
    if not pd.api.types.is_numeric_dtype(table["coef"]):
        contract_fail(where, "column coef has dtype {}".format(table["coef"].dtype), "numeric coef")
    out = table[FEATURE_INPUT_COLUMNS].reset_index(drop=True).copy()
    out["coef"] = out["coef"].astype(float)
    if out["feature"].isna().any() or out["view"].isna().any():
        contract_fail(where, "missing values in column feature or view", "no missing feature or view names")
    if not np.isfinite(out["coef"].values).all():
        bad = int((~np.isfinite(out["coef"].values)).sum())
        contract_fail(
            where,
            "{} NaN or infinite values in column coef".format(bad),
            "finite coef values. Use 0 for a feature with no weight",
        )
    unknown = sorted(set(out["view"]) - set(X))
    if unknown:
        contract_fail(
            where,
            "unknown views: {}".format(", ".join(str(v) for v in unknown)),
            "views from: {}".format(", ".join(X)),
        )
    for view, rows in out.groupby("view"):
        bad = sorted(set(rows["feature"]) - set(X[view].columns), key=str)
        if bad:
            contract_fail(
                where,
                "{} features not in view '{}', such as '{}'".format(len(bad), view, bad[0]),
                "feature names exactly as in X_train[view].columns",
            )
    if out.duplicated(["feature", "view"]).any():
        contract_fail(where, "duplicated feature and view pairs", "one row per feature within a view")
    return out


def build_result_table(phat, samples, y, method, dataset, fold):
    """The table that combine_tables.R and the metrics scripts read."""
    table = pd.DataFrame(
        {
            "sample_name": [str(s) for s in samples],
            "y": np.asarray(y).astype(int),
            "phat": np.round(phat, PHAT_DECIMALS),
            "method_name": method,
            "dataset": dataset,
            "fold": fold,
        }
    )[RESULT_COLUMNS]
    validate_result_table(table, samples)
    return table


def validate_result_table(table, samples):
    where = "the result table"
    if list(table.columns) != RESULT_COLUMNS:
        contract_fail(where, ", ".join(table.columns), ", ".join(RESULT_COLUMNS))
    if list(table["sample_name"]) != [str(s) for s in samples]:
        contract_fail(
            where,
            "{} rows that do not match the test samples".format(len(table)),
            "one row for each of the {} test samples".format(len(samples)),
        )
    if not table["y"].isin([0, 1]).all():
        contract_fail(where, "y values other than 0 and 1", "y is 0 or 1")
    if not pd.api.types.is_numeric_dtype(table["phat"]) or table["phat"].isna().any():
        contract_fail(where, "non-numeric or missing phat", "numeric phat without NaN")
    return table


def build_feature_table(features, method, dataset):
    """The table that merge_selected_features.R reads."""
    table = features.copy()
    table["method"] = method
    table["dataset_name"] = dataset
    return table[FEATURE_COLUMNS]


def build_hyperparameter_record(hyperparameters, method, dataset, seed):
    """The record that merge_selected_hyperparameters.py reads.

    hyperparameters is the optional HYPERPARAMETERS dict of the core file: plain values
    are recorded as "fixed"; use {"value": ..., "treatment": ...} otherwise.
    """
    parameters = {}
    for name, item in (hyperparameters or {}).items():
        if not (isinstance(item, dict) and "value" in item and "treatment" in item):
            item = {"value": item, "treatment": "fixed"}
        if item["treatment"] not in TREATMENTS:
            contract_fail(
                "HYPERPARAMETERS",
                "treatment '{}' for {}".format(item["treatment"], name),
                "one of: {}".format(", ".join(TREATMENTS)),
            )
        parameters[name] = {"value": item["value"], "treatment": item["treatment"]}
    parameters["seed"] = {"value": int(seed), "treatment": "data-derived"}
    record = {
        "run_id": "{}-{}".format(method, dataset),
        "dataset": dataset,
        "method": method,
        "analysis_stage": "model_selection",
        "selection": {"strategy": "fit_on_all_samples"},
        "parameters": parameters,
    }
    missing = [f for f in HYPERPARAMETER_FIELDS if f not in record]
    if missing:
        contract_fail("the hyperparameter record", ", ".join(record), ", ".join(HYPERPARAMETER_FIELDS))
    return record


def write_result_csv(table, path):
    table.to_csv(path, index=False)


def write_feature_csv(table, path):
    table.to_csv(path, index=False)


def write_hyperparameter_json(record, path):
    with open(path, "w") as handle:
        json.dump(record, handle, indent=2, default=str)


def seed_from_label(label, prime=999983):
    """Same rule as label_to_seed() in the existing Python methods."""
    return int(hashlib.sha256(label.encode()).hexdigest(), 16) % prime
